(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.NetView=api;})(globalThis,function(){
const pos={K:[60,160],A:[180,160],L:[180,50],B:[320,65],C:[320,250],D:[460,160],W:[590,160]},names={K:'Client',A:'Weiterleitung',B:'Weiterleitung',C:'Weiterleitung',D:'Weiterleitung',L:'lokaler Dienst',W:'ferner Dienst'};
function svg(disabled=[],at='',compact=false){const points=compact?{K:[25,135],A:[105,135],L:[105,35],B:[220,50],C:[220,220],D:[330,135],W:[415,135]}:pos;const edges=['K-A','A-L','A-B','A-C','B-C','B-D','C-D','D-W'];return '<svg class="net-graph" viewBox="0 0 '+(compact?'440 250':'660 300')+'" role="img" aria-label="Netzmodell. Die Verbindungen und ihr Zustand stehen auch als Text unter der Grafik.">'+edges.map(e=>{const [a,b]=e.split('-'),off=disabled.includes(e),x=(points[a][0]+points[b][0])/2,y=(points[a][1]+points[b][1])/2;return '<line x1="'+points[a][0]+'" y1="'+points[a][1]+'" x2="'+points[b][0]+'" y2="'+points[b][1]+'" stroke="'+(off?'#92351d':'#768291')+'" stroke-width="3"'+(off?' stroke-dasharray="6 5"':'')+'/>'+(off?'<text x="'+x+'" y="'+(y-5)+'" class="net-cut">×</text>':'');}).join('')+Object.entries(points).map(([n,[x,y]])=>'<circle cx="'+x+'" cy="'+y+'" r="21" fill="'+(n===at?'#ffd478':'#fff')+'" stroke="#0A7A70" stroke-width="3"/><text x="'+x+'" y="'+(y+6)+'" text-anchor="middle" font-weight="700" font-size="'+(compact?28:18)+'">'+n+'</text>'+(compact?'':'<text x="'+x+'" y="'+(y+40)+'" text-anchor="middle" font-size="16">'+names[n]+'</text>')).join('')+'</svg>';}
return {svg};});
